<?php
declare(strict_types=1);namespace app\common\service\storage\driver;
use app\common\service\storage\StorageDriver;use app\common\service\storage\StoragePath;use OSS\OssClient;
final readonly class AliyunStorageDriver implements StorageDriver
{public function __construct(private array $account,private array $space){}public function put(string $k,string $p):void{$this->client()->uploadFile((string)$this->space['bucket'],StoragePath::assertObjectKey($k),$p);}public function delete(string $k):void{$this->client()->deleteObject((string)$this->space['bucket'],StoragePath::assertObjectKey($k));}public function publicUrl(string $k):string{$d=rtrim((string)($this->space['access_domain']??''),'/');if($d==='')throw new \RuntimeException('阿里云访问域名未配置');return$d.'/'.StoragePath::assertObjectKey($k);}public function temporaryUrl(string $k,int $e,string $f,string $d):string{return$this->client()->signUrl((string)$this->space['bucket'],StoragePath::assertObjectKey($k),$e,OssClient::OSS_HTTP_GET,[OssClient::OSS_CONTENT_DISPOSITION=>sprintf('%s; filename="%s"',$d,addslashes($f))]);}public function localPath(string $k):?string{return null;}private function client():OssClient{$c=(array)$this->account['credentials'];return new OssClient((string)$c['access_key'],(string)$c['secret_key'],(string)$this->space['endpoint'],true);}}
